/// A running machine saved at a macrostep boundary, and restored into a new
/// process in place of `initialize` — every variable, the machine's own
/// included, and where the machine stands. The saved state is JSON
/// (`SavedState::to_json`), the same on every backend.
pub trait SheetPeerPersist: Sized {
    /// The policy a restored machine is built around, constructed by the host
    /// as it would be for `initialize`.
    type Policy;

    /// The shape a saved state of this document is bound to: a state saved
    /// from a document that renamed, re-typed or moved a state or a variable
    /// is refused, one saved before a guard or an action changed is not.
    const SHAPE: &'static str;

    /// The document's `<history>` pseudo-states, by the id a saved state keys
    /// them by — what a saved state records of each, and what a restore reads
    /// back. Empty for a document that declares none.
    const HISTORIES: &'static [::sce_rust_runtime::saved_state::HistoryDecl<
        ::sce_rust_runtime::NoHistory,
    >];

    /// The machine's whole state, each delayed `<send>` still waiting written
    /// as the moment it comes due on the wall clock whose reading now is
    /// `wall_now_ms`, in milliseconds since the Unix epoch. Refused for a
    /// machine that is not running, and for one whose last macrostep stopped
    /// at the microstep ceiling.
    fn save_at(
        &self,
        wall_now_ms: u64,
    ) -> Result<
        ::sce_rust_runtime::saved_state::SavedState,
        ::sce_rust_runtime::saved_state::StateRefusal,
    >;

    /// [`save_at`](Self::save_at) at the host's wall clock now.
    ///
    /// Absent on `wasm32-unknown-unknown`, which provides no wall clock to read:
    /// a host there says what time it is, through [`save_at`](Self::save_at).
    #[cfg(not(all(target_arch = "wasm32", target_os = "unknown")))]
    fn save(
        &self,
    ) -> Result<
        ::sce_rust_runtime::saved_state::SavedState,
        ::sce_rust_runtime::saved_state::StateRefusal,
    > {
        self.save_at(::sce_rust_runtime::saved_state::wall_clock_ms())
    }

    /// A machine of `policy` standing where `saved` left one, measuring time
    /// by `clock` and told by `wall_now_ms` what time it is on the wall clock
    /// the saved `due`s were written against: a waiting send comes due when
    /// its saved moment does, and one already due comes due now. No
    /// `<onentry>` runs and no `<data>` is evaluated: the saved run already
    /// did both.
    fn restore_with(
        policy: Self::Policy,
        saved: &::sce_rust_runtime::saved_state::SavedState,
        clock: ::sce_rust_runtime::SceClock,
        wall_now_ms: u64,
    ) -> Result<Self, ::sce_rust_runtime::saved_state::StateRefusal>;

    /// [`restore_with`](Self::restore_with) on the engine's own clock, at the
    /// host's wall clock now.
    ///
    /// Absent on `wasm32-unknown-unknown`, for the reason [`save`](Self::save)
    /// is: a host there gives the clock and the wall time to
    /// [`restore_with`](Self::restore_with).
    #[cfg(not(all(target_arch = "wasm32", target_os = "unknown")))]
    fn restore(
        policy: Self::Policy,
        saved: &::sce_rust_runtime::saved_state::SavedState,
    ) -> Result<Self, ::sce_rust_runtime::saved_state::StateRefusal> {
        Self::restore_with(
            policy,
            saved,
            ::sce_rust_runtime::SceClock::default(),
            ::sce_rust_runtime::saved_state::wall_clock_ms(),
        )
    }
}

impl SheetPeerPersist for Engine<SheetPeerPolicy> {
    type Policy = SheetPeerPolicy;

    const SHAPE: &'static str = "1ac6b3f2603c6108cd17580f835aab53156fb15bf1be7c02a34b837cfb45cf6f";

    const HISTORIES: &'static [::sce_rust_runtime::saved_state::HistoryDecl<
        ::sce_rust_runtime::NoHistory,
    >] = &[];

    fn save_at(
        &self,
        wall_now_ms: u64,
    ) -> Result<
        ::sce_rust_runtime::saved_state::SavedState,
        ::sce_rust_runtime::saved_state::StateRefusal,
    > {
        let policy = self.policy();
        ::sce_rust_runtime::saved_state::save(
            self,
            Self::SHAPE,
            vec![
                (
                    "node".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.node),
                ),
                (
                    "hub".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.hub),
                ),
                (
                    "clock".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.clock),
                ),
                (
                    "stamp".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.stamp),
                ),
                (
                    "cells".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.cells),
                ),
                (
                    "rows".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.rows),
                ),
                (
                    "gone".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.gone),
                ),
                (
                    "cols".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.cols),
                ),
                (
                    "goneCols".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.gone_cols),
                ),
                (
                    "trail".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.trail),
                ),
                (
                    "shown".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.shown),
                ),
                (
                    "write".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.write),
                ),
                (
                    "placed".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.placed),
                ),
                (
                    "removal".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.removal),
                ),
                (
                    "lamport".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.lamport),
                ),
                (
                    "newKey".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.new_key),
                ),
                (
                    "noKey".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.no_key),
                ),
                (
                    "noNumber".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.no_number),
                ),
                (
                    "orphans".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.orphans),
                ),
                (
                    "refusals".to_string(),
                    ::sce_rust_runtime::saved_state::SavedValue::to_saved(&policy.refusals),
                ),
            ],
            ::sce_rust_runtime::saved_state::save_history(self.policy(), Self::HISTORIES),
            wall_now_ms,
        )
    }

    fn restore_with(
        mut policy: SheetPeerPolicy,
        saved: &::sce_rust_runtime::saved_state::SavedState,
        clock: ::sce_rust_runtime::SceClock,
        wall_now_ms: u64,
    ) -> Result<Self, ::sce_rust_runtime::saved_state::StateRefusal> {
        ::sce_rust_runtime::saved_state::check_shape(saved, Self::SHAPE)?;
        // Judged with the configuration and before any value is written, so a
        // refused restore holds no half of a state. A document with no
        // `<history>` refuses any a saved state records.
        ::sce_rust_runtime::saved_state::restore_history::<SheetPeerPolicy>(
            saved,
            Self::HISTORIES,
        )?;
        policy.node = ::sce_rust_runtime::saved_state::SavedValue::from_saved(
            saved.variable("node")?,
            "node",
        )?;
        policy.hub =
            ::sce_rust_runtime::saved_state::SavedValue::from_saved(saved.variable("hub")?, "hub")?;
        policy.clock = ::sce_rust_runtime::saved_state::SavedValue::from_saved(
            saved.variable("clock")?,
            "clock",
        )?;
        policy.stamp = ::sce_rust_runtime::saved_state::SavedValue::from_saved(
            saved.variable("stamp")?,
            "stamp",
        )?;
        policy.cells =
            ::sce_rust_runtime::saved_state::bounded(saved.variable("cells")?, "cells", 256)?;
        policy.rows =
            ::sce_rust_runtime::saved_state::bounded(saved.variable("rows")?, "rows", 256)?;
        policy.gone =
            ::sce_rust_runtime::saved_state::bounded(saved.variable("gone")?, "gone", 256)?;
        policy.cols =
            ::sce_rust_runtime::saved_state::bounded(saved.variable("cols")?, "cols", 256)?;
        policy.gone_cols =
            ::sce_rust_runtime::saved_state::bounded(saved.variable("goneCols")?, "goneCols", 256)?;
        policy.trail =
            ::sce_rust_runtime::saved_state::bounded(saved.variable("trail")?, "trail", 768)?;
        policy.shown =
            ::sce_rust_runtime::saved_state::bounded(saved.variable("shown")?, "shown", 256)?;
        policy.write = ::sce_rust_runtime::saved_state::SavedValue::from_saved(
            saved.variable("write")?,
            "write",
        )?;
        policy.placed = ::sce_rust_runtime::saved_state::SavedValue::from_saved(
            saved.variable("placed")?,
            "placed",
        )?;
        policy.removal = ::sce_rust_runtime::saved_state::SavedValue::from_saved(
            saved.variable("removal")?,
            "removal",
        )?;
        policy.lamport = ::sce_rust_runtime::saved_state::SavedValue::from_saved(
            saved.variable("lamport")?,
            "lamport",
        )?;
        policy.new_key = ::sce_rust_runtime::saved_state::SavedValue::from_saved(
            saved.variable("newKey")?,
            "newKey",
        )?;
        policy.no_key = ::sce_rust_runtime::saved_state::SavedValue::from_saved(
            saved.variable("noKey")?,
            "noKey",
        )?;
        policy.no_number = ::sce_rust_runtime::saved_state::SavedValue::from_saved(
            saved.variable("noNumber")?,
            "noNumber",
        )?;
        policy.orphans = ::sce_rust_runtime::saved_state::SavedValue::from_saved(
            saved.variable("orphans")?,
            "orphans",
        )?;
        policy.refusals = ::sce_rust_runtime::saved_state::SavedValue::from_saved(
            saved.variable("refusals")?,
            "refusals",
        )?;
        ::sce_rust_runtime::saved_state::enter(policy, saved, clock, wall_now_ms)
    }
}

